insert into public.exam_defs(stage,minutes,items) values (1,40,'{"parts": [{"id": "dictation", "title": "Part 1 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 15}, {"id": "yesno", "title": "Part 2 · Yes / No quiz", "instr": "Listen to your teacher’s questions. Answer every question: Yes, No or ?. Press ? if you did not understand the question. You lose 1 mark for each wrong answer; ? scores 0.", "n": 15, "points": 15}, {"id": "mc", "title": "Part 3 · Multiple choice", "instr": "Choose the correct answer.", "points": 12, "items": [{"n": 1, "q": "We haven’t got ____ books in our bags.", "opts": {"a": "any", "b": "some", "c": "none"}}, {"n": 2, "q": "Are ____ pencils on the table white?", "opts": {"a": "there", "b": "they", "c": "those"}}, {"n": 3, "q": "The people of Scandinavia aren’t short; they’re ____ .", "opts": {"a": "tall", "b": "high", "c": "long"}}, {"n": 4, "q": "Serena and Mary ____ speak in the lesson.", "opts": {"a": "doesn’t", "b": "aren’t", "c": "don’t"}}, {"n": 5, "q": "the first question on this page into German.", "opts": {"a": "Say", "b": "Translate", "c": "Answer"}}, {"n": 6, "q": "Jack can’t ____ in French.", "opts": {"a": "to read", "b": "read", "c": "reading"}}, {"n": 7, "q": "Are ____ the students staying here in the room?", "opts": {"a": "any", "b": "some", "c": "all"}}, {"n": 8, "q": "is the man in that room? Is he David Jones?", "opts": {"a": "Who", "b": "What", "c": "How"}}, {"n": 9, "q": "Mrs Black teaches that class. She is ____ English teacher.", "opts": {"a": "them", "b": "their", "c": "they"}}, {"n": 10, "q": "I am ____ you a question.", "opts": {"a": "asking", "b": "asking to", "c": "asking for"}}, {"n": 11, "q": "Jack is taking the ____ book from the table.", "opts": {"a": "close", "b": "closing", "c": "closed"}}, {"n": 12, "q": "Is the teacher ____ now?", "opts": {"a": "listens", "b": "listening", "c": "listen"}}]}, {"id": "err", "title": "Part 4 · Error correction", "instr": "Correct the mistake in each sentence. You can add one word, take out one word, or change one word. Type the whole corrected sentence.", "points": 8, "items": [{"n": 1, "text": "Are you going to home now?"}, {"n": 2, "text": "The man isn’t moving; is still."}, {"n": 3, "text": "What’s the difference the present simple and the present continuous?"}, {"n": 4, "text": "That women has got a yellow bag and brown shoes."}, {"n": 5, "text": "My foots are under my chair."}, {"n": 6, "text": "The teacher is asking to us questions in English."}, {"n": 7, "text": "Are you writes in your book with a pencil or a pen?"}, {"n": 8, "text": "Where are those Chinese person studying?"}]}]}'::jsonb) on conflict (stage) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,keys) values (1,'{"parts": [{"id": "dictation", "points": 15, "text": "Where’s the capital city of your country? The wall’s low. In the alphabet, G is before H, whereas I is after it. Stand in front of me. Which girl’s wearing a skirt? Please pronounce these letters. That’s wrong. I cannot write with my right hand. I use my left hand. She generally speaks Chinese. Their eyes are blue. What’s the meaning of “goodbye” in Italian? They’re in the classroom. How many people are there here at the school? There aren’t a hundred. It isn’t a small town; it’s a large village. Touch your head and your ears. Come here and sit on the floor. His family’s Japanese, but he’s speaking English now. My jacket is completely black."}, {"id": "yesno", "points": 15, "keys": {"1": "No", "2": "Yes", "3": "Yes", "4": "Yes", "5": "No", "6": "Yes", "7": "No", "8": "Yes", "9": "No", "10": "Yes", "11": "Yes", "12": "No", "13": "No", "14": "Yes", "15": "No"}, "teacher": {"1": "Is your chin part of your arm?", "2": "When a teacher gives a class a dictation, do the students listen and write?", "3": "Is the letter J a consonant?", "4": "In the English alphabet, are the letters L and M between K and N?", "5": "Am I answering your questions?", "6": "Is the word “sentence” the last word in this sentence?", "7": "Is fifty minus nine fifty-nine?", "8": "Are there five vowels in the English alphabet?", "9": "Can we wear a clock?", "10": "Two plus two equals ten. Is that wrong?", "11": "Have you got two thumbs?", "12": "Has the word “putting” got one T in it?", "13": "Is the word “goes” the imperative of the verb “go”?", "14": "Is the floor under your chair?", "15": "When a person says “Thanks”, is it right to say “It’s welcome”?"}}, {"id": "mc", "points": 12, "keys": {"1": "a", "2": "c", "3": "a", "4": "c", "5": "b", "6": "b", "7": "c", "8": "a", "9": "b", "10": "a", "11": "c", "12": "b"}}, {"id": "err", "points": 8, "accept": {"1": ["Are you going home now?"], "2": ["The man isn’t moving; he is still."], "3": ["What’s the difference between the present simple and the present continuous?"], "4": ["That woman has got a yellow bag and brown shoes."], "5": ["My feet are under my chair."], "6": ["The teacher is asking us questions in English."], "7": ["Are you writing in your book with a pencil or a pen?"], "8": ["Where are those Chinese people studying?"]}, "hint": {"1": "Take out “to” – “going home”", "2": "Add “he” – “he is still”", "3": "Add “between” – “difference between the”", "4": "Change “women” to “woman”", "5": "Change “foots” to “feet”", "6": "Take out “to” – “asking us”", "7": "Change “writes” to “writing”", "8": "Change “person” to “people”"}}]}'::jsonb) on conflict (stage) do update set keys=excluded.keys;
insert into public.exam_defs(stage,minutes,items) values (2,40,'{"parts": [{"id": "dictation", "title": "Part 1 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 15}, {"id": "yesno", "title": "Part 2 · Yes / No quiz", "instr": "Listen to your teacher’s questions. Answer every question: Yes, No or ?. Press ? if you did not understand the question. You lose 1 mark for each wrong answer; ? scores 0.", "n": 15, "points": 15}, {"id": "mc", "title": "Part 3 · Multiple choice", "instr": "Choose the correct answer.", "points": 12, "items": [{"n": 1, "q": "The plant in your living room is ____ to the one I have in my kitchen.", "opts": {"a": "similar", "b": "the same", "c": "like"}}, {"n": 2, "q": "I go to work ____ foot. I don’t use my car.", "opts": {"a": "at", "b": "with", "c": "on"}}, {"n": 3, "q": "The house next ____ yours has large windows.", "opts": {"a": "to", "b": "by", "c": "of"}}, {"n": 4, "q": "My father generally goes to ____ at 10.30 p.m.", "opts": {"a": "his bed", "b": "bed", "c": "the bed"}}, {"n": 5, "q": "Languages such ____ French and Italian are European.", "opts": {"a": "like", "b": "as", "c": "of"}}, {"n": 6, "q": "Anna can’t touch the top of the door; she isn’t ____ to do that.", "opts": {"a": "tall enough", "b": "too tall", "c": "tall for"}}, {"n": 7, "q": "I don’t want to play tennis. I know I’m bad ____ it, and I don’t like it.", "opts": {"a": "in", "b": "at", "c": "for"}}, {"n": 8, "q": "Come to my house ____ bus. It’s cheaper than the train.", "opts": {"a": "in", "b": "with", "c": "by"}}, {"n": 9, "q": "Fernanda cannot speak to you now; she’s ____ a call to her mother.", "opts": {"a": "doing", "b": "having", "c": "making"}}, {"n": 10, "q": "Why has my glass got the ____ water in it? Can I have more, please?", "opts": {"a": "least", "b": "less", "c": "little"}}, {"n": 11, "q": "Our piano isn’t ____ than your piano.", "opts": {"a": "most expensive", "b": "expensiver", "c": "more expensive"}}, {"n": 12, "q": "Do you prefer coffee ____ tea?", "opts": {"a": "than", "b": "to", "c": "for"}}]}, {"id": "err", "title": "Part 4 · Error correction", "instr": "Correct the mistake in each sentence. You can add one word, take out one word, or change one word. Type the whole corrected sentence.", "points": 8, "items": [{"n": 1, "text": "Some of my friends like meat but the most only eat fruit and vegetables."}, {"n": 2, "text": "I don’t think that Mrs Brown house has got any blue windows; they’re all white."}, {"n": 3, "text": "I’ve got two sisters. Both them have black hair, but my hair’s brown."}, {"n": 4, "text": "Was the month before the last April or May?"}, {"n": 5, "text": "Do you know to open that box in the corner? Nobody here can do it."}, {"n": 6, "text": "You know my name. Why can’t you tell to me yours?"}, {"n": 7, "text": "Sandra isn’t Italian. I think she’s either English either German."}, {"n": 8, "text": "I want to eat rice for lunch today instead bread."}]}]}'::jsonb) on conflict (stage) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,keys) values (2,'{"parts": [{"id": "dictation", "points": 15, "text": "February’s the month between January and March. My daughter can drive, but hers can’t. The watch on her wrist says it’s midday. I don’t hate the weekend. Give me the salt and the pepper, please. We’re walking into the garden. It has many flowers in it, and there are also three trees. That isn’t my cousin’s building. Where are the students? It’s nine o’clock and nobody’s in the corridor. Whose guitar are you playing? That meal is too large for my small stomach. About half the people in this class are friendly. How can he eat breakfast if he hasn’t got a knife and fork? Are those drinks theirs? No, they’re ours. During the lesson, we count in Spanish."}, {"id": "yesno", "points": 15, "keys": {"1": "Yes", "2": "No", "3": "Yes", "4": "No", "5": "No", "6": "No", "7": "Yes", "8": "Yes", "9": "No", "10": "Yes", "11": "No", "12": "Yes", "13": "No", "14": "No", "15": "Yes"}, "teacher": {"1": "Is the word “right” the opposite of both “left” and “wrong”?", "2": "Is stone a kind of metal?", "3": "Do keys open things?", "4": "Do sixteen minutes make one hour?", "5": "Are my uncles and aunts my parents?", "6": "Can we hear well with our fingers in our ears?", "7": "Is an only child somebody without brothers or sisters?", "8": "Can we put food into our mouths with a spoon?", "9": "Are the clothes you’re wearing mine?", "10": "Can we see the outside of a box when it’s closed?", "11": "Is it difficult to learn easy things?", "12": "Can we smell without using our eyes?", "13": "Does the plural of “child” have one syllable?", "14": "Do people generally want to live in ugly houses?", "15": "Do courses last longer than lessons?"}}, {"id": "mc", "points": 12, "keys": {"1": "a", "2": "c", "3": "a", "4": "b", "5": "b", "6": "a", "7": "b", "8": "c", "9": "c", "10": "a", "11": "c", "12": "b"}}, {"id": "err", "points": 8, "accept": {"1": ["Some of my friends like meat but most only eat fruit and vegetables."], "2": ["I don’t think that Mrs Brown’s house has got any blue windows; they’re all white."], "3": ["I’ve got two sisters. Both of them have black hair, but my hair’s brown."], "4": ["Was the month before last April or May?"], "5": ["Do you know how to open that box in the corner? Nobody here can do it."], "6": ["You know my name. Why can’t you tell me yours?"], "7": ["Sandra isn’t Italian. I think she’s either English or German."], "8": ["I want to eat rice for lunch today instead of bread."]}, "hint": {"1": "Take out “the” – “but most”", "2": "Change “Brown” to “Brown’s”", "3": "Add “of” – “both of them”", "4": "Take out “the” – “before last”", "5": "Add “how” – “know how to”", "6": "Take out “to” – “tell me”", "7": "Change “either German” to “or German”", "8": "Add “of” – “instead of bread”"}}]}'::jsonb) on conflict (stage) do update set keys=excluded.keys;
